{"function":"() => {
const res=[];
function walk(root){
  for (const el of root.querySelectorAll('*')){
    if (el.shadowRoot) walk(el.shadowRoot);
    const t = el.tabIndex;
    const focusable = el.matches('a[href],button:not([disabled]),input:not([disabled]),select,textarea,[tabindex]');
    if (focusable && t>=0){
      const r=el.getBoundingClientRect();
      if (r.width>0) res.push(el.tagName+'#'+el.id+'.'+(el.className||'').toString().slice(0,30)+' "'+(el.getAttribute('aria-label')??'')+'|'+el.textContent.trim().slice(0,25)+'" ti='+el.getAttribute('tabindex'));
    }
  }
}
walk(document);
return res.slice(0,40);
}"}

